    if ($fileId === 0) {
        return $collectiveFolder;
    }
    $file = $this->nodeHelper->getFileById($collectiveFolder, $fileId);
    if (!$file->getParent() instanceof \OCP\Files\Folder) {
        throw new \OCA\Collectives\Service\NotFoundException('Error getting parent folder for file ' . $fileId . ' in collective ' . $collectiveId);
    }
    return $file->getParent();
}

/**
