    } catch (\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    if (!$file instanceof \OCP\Files\File) {
        throw new \OCA\Collectives\Service\NotFoundException('Failed to get index page');
    }
