private function createFileSearcher(): \OCA\Collectives\Search\FileSearch\FileSearcher
{
    $defaultLanguage = $this->config->getSystemValue('default_language', 'en');
    return new \OCA\Collectives\Search\FileSearch\FileSearcher(\OCA\Collectives\Search\FileSearch\FileSearcher::SUPPORTED_LANGUAGES[$defaultLanguage] ?? null);
