public function getCircle(string $circleId, ?string $userId = null, bool $super = false): \OCA\Circles\Model\Circle
{
    try {
        if ($super) {
            $this->startSuperSession();
        } else {
            $this->startSession($userId);
        }
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        $circle = $this->circlesManager->getCircle($circleId);
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    $this->circlesManager->stopSession();
    return $circle;
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getCircles(?string $userId = null): array
{
    try {
        $this->startSession($userId);
        $circleProbe = new \OCA\Circles\Model\Probes\CircleProbe();
        $circleProbe->mustBeMember();
        $dataProbe = new \OCA\Circles\Model\Probes\DataProbe();
        $dataProbe->add(\OCA\Circles\Model\Probes\DataProbe::INITIATOR);
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        $circles = self::useProbeCircles() ? $this->circlesManager->probeCircles($circleProbe, $dataProbe) : $this->circlesManager->getCircles($circleProbe, true);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    $this->circlesManager->stopSession();
    return $circles;
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 */
private function getFederatedUser(?string $userId = null): ?\OCA\Circles\Model\FederatedUser
{
    if ($userId === null) {
        return null;
    }
    try {
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        return $this->circlesManager->getFederatedUser($userId, \OCA\Circles\Model\Member::TYPE_USER);
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\FederatedItemException|\OCA\Circles\Exceptions\RequestBuilderException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getLevel(string $circleId, string $userId): int
{
    if (is_null($this->circlesManager)) {
        throw new \OCA\Collectives\Service\MissingDependencyException($this->dependencyInjectionError);
    }
    try {
        $this->startSession($userId);
        $circle = $this->circlesManager->getCircle($circleId);
        $member = $circle->getInitiator();
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    return $member->getLevel();
}

/**
