/**
 * Use `probeCircles()` on
 * - Nextcloud 31+
 * - Nextcloud 30 starting with 30.0.3
 */
private static function useProbeCircles(): bool
{
    [$major, $minor, $micro] = \OCP\Util::getVersion();
    $version = $major . '.' . $minor . '.' . $micro;
    return $major >= 31 || $major === 30 && version_compare($version, '30.0.3', '>=');
}

