/**
 * @param string $indexName
 * @throws FileSearchException
 */
public function selectIndex($indexName): \OCA\Collectives\Search\FileSearch\FileIndexer
{
    if (!file_exists($indexName)) {
        throw new \OCA\Collectives\Search\FileSearch\FileSearchException('Could not find an index for the collective.');
    }
    $this->index = new \PDO('sqlite:' . $indexName);
    $this->index->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
    $this->indexer->setIndex($this->index);
    $this->indexer->setLanguage($this->language ?? self::UNSUPPORTED_LANGUAGE);
    return $this->indexer;
}

/**
 * @throws FileSearchException
 */
public function selectIndexFile(\OCP\Files\File $indexFile): \OCA\Collectives\Search\FileSearch\FileIndexer
{
    try {
        $path = $indexFile->getStorage()->getLocalFile($indexFile->getInternalPath());
    } catch (\OCP\Files\NotFoundException) {
        throw new \OCA\Collectives\Search\FileSearch\FileSearchException('File searcher could not find storage for index file.');
    }
    if (!$path) {
        throw new \OCA\Collectives\Search\FileSearch\FileSearchException('File searcher could not create local index.');
    }
    return $this->selectIndex($path);
}

