private function createFileSearcher(): \OCA\Collectives\Search\FileSearch\FileSearcher
{
    $defaultLanguage = $this->config->getSystemValue('default_language', 'en');
    return new \OCA\Collectives\Search\FileSearch\FileSearcher(\OCA\Collectives\Search\FileSearch\FileSearcher::SUPPORTED_LANGUAGES[$defaultLanguage] ?? null);
}

/**
 * @throws FileSearchException
 */
public function getIndexForCollective(\OCA\Collectives\Db\Collective $collective): ?\OCP\Files\File
{
    try {
        $file = $this->getIndicesFolder()->get($this->getIndexName($collective));
    } catch (\OCP\Files\NotFoundException) {
        return null;
    }
    return $file instanceof \OCP\Files\File ? $file : null;
}

/**
 * @throws FileSearchException
 */
private function getIndicesFolder(): \OCP\Files\Folder
{
    $rootFolder = $this->collectiveFolderManager->getRootFolder();
    try {
        $folder = $rootFolder->get(self::INDICES_DIR_NAME);
        if ($folder instanceof \OCP\Files\Folder) {
            return $folder;
        }
    } catch (\OCP\Files\NotFoundException) {
    }
    try {
        return $rootFolder->newFolder(self::INDICES_DIR_NAME);
    } catch (\OCP\Files\NotPermittedException) {
        throw new \OCA\Collectives\Search\FileSearch\FileSearchException('Could not find or create the indices directory.');
    }
}

/**
 * @throws FileSearchException
 */
public function searchCollective(\OCA\Collectives\Db\Collective $collective, string $term, int $maxResults = 15): array
{
    if (!$this->areDependenciesMet()) {
        $this->logger->warning('Collectives full-text search is not operational, because the PDO SQLite driver is not available.');
        return [];
    }
    $searcher = $this->createFileSearcher();
    $file = $this->getIndexForCollective($collective);
    if ($file === null) {
        $this->logger->warning('Collectives search failed to find search index for collective with ID ' . $collective->getId());
        return [];
    }
    $searcher->selectIndexFile($file);
    return $searcher->search($term, $maxResults);
}

