/**
 * @throws NotFoundException
 */
private function getParentPageId(\OCP\Files\File $file, ?\OCP\Files\Node $parent = null): int
{
    try {
        if (\OCA\Collectives\Fs\NodeHelper::isLandingPage($file)) {
            // Return `0` for landing page
            return 0;
        }
        $parent ??= $file->getParent();
        if (\OCA\Collectives\Fs\NodeHelper::isIndexPage($file)) {
            // Go down two levels if index page but not landing page
            return self::getIndexPageFile($parent->getParent())->getId();
        }
        return self::getIndexPageFile($parent)->getId();
    } catch (\OCP\Files\InvalidPathException|\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
}

