 */
public static function getIndexPageFile(\OCP\Files\Folder $folder): \OCP\Files\File
{
    try {
        $file = $folder->get(\OCA\Collectives\Model\PageInfo::INDEX_PAGE_TITLE . \OCA\Collectives\Model\PageInfo::SUFFIX);
    } catch (\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    if (!$file instanceof \OCP\Files\File) {
        throw new \OCA\Collectives\Service\NotFoundException('Failed to get index page');
    }
    return $file;
}

/**
 * @throws NotFoundException
 */
private function getPageByFile(\OCP\Files\File $file, ?\OCP\Files\Node $parent = null): \OCA\Collectives\Model\PageInfo
{
    try {
        $page = $this->pageMapper->findByFileId($file->getId());
    } catch (\OCP\Files\InvalidPathException|\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    $lastUserId = $page !== null ? $page->getLastUserId() : null;
    $emoji = $page !== null ? $page->getEmoji() : null;
    $subpageOrder = $page !== null ? $page->getSubpageOrder() : null;
    $fullWidth = $page !== null && $page->getFullWidth();
    $slug = $page !== null ? $page->getSlug() : null;
    $tags = $page !== null ? $page->getTags() : null;
    $linkedPageIds = $page !== null ? $this->pageLinkMapper->findByPageId($page->getFileId()) : null;
    $pageInfo = new \OCA\Collectives\Model\PageInfo();
    try {
        $pageInfo->fromFile($file, $this->getParentPageId($file, $parent), $lastUserId, $lastUserId ? $this->userManager->getDisplayName($lastUserId) : null, $emoji, $subpageOrder, $fullWidth, $slug, $tags, $linkedPageIds);
    } catch (\OCP\Files\NotFoundException|\OCP\Files\InvalidPathException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    return $pageInfo;
}

/**
 * @throws MissingDependencyException
 * @throws NotFoundException
 * @throws NotPermittedException
 */
public function getPageFile(int $collectiveId, int $fileId, string $userId): \OCP\Files\File
{
    $collectiveFolder = $this->getCollectiveFolder($collectiveId, $userId);
    return $this->nodeHelper->getFileById($collectiveFolder, $fileId);
}

/**
 * @throws NotFoundException
 */
private function getParentPageId(\OCP\Files\File $file, ?\OCP\Files\Node $parent = null): int
{
    try {
        if (\OCA\Collectives\Fs\NodeHelper::isLandingPage($file)) {
            // Return `0` for landing page
            return 0;
        }
        $parent ??= $file->getParent();
        if (\OCA\Collectives\Fs\NodeHelper::isIndexPage($file)) {
            // Go down two levels if index page but not landing page
            return self::getIndexPageFile($parent->getParent())->getId();
        }
        return self::getIndexPageFile($parent)->getId();
    } catch (\OCP\Files\InvalidPathException|\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
}

