public function findDocumentsByWords(int $collectiveId, array $wordIds, int $limit): array
{
    $qb = $this->db->getQueryBuilder();
    $qb->select('d.file_id')->selectAlias($qb->func()->sum('d.hit_count'), 'total_hits')->from($this->tableName, 'd')->innerJoin('d', 'collectives_s_words', 'w', $qb->expr()->eq('d.word_id', 'w.id'))->where($qb->expr()->eq('d.collective_id', $qb->createNamedParameter($collectiveId, \OCP\DB\QueryBuilder\IQueryBuilder::PARAM_INT)))->andWhere($qb->expr()->in('d.word_id', $qb->createNamedParameter($wordIds, \OCP\DB\QueryBuilder\IQueryBuilder::PARAM_INT_ARRAY)))->groupBy('d.file_id')->orderBy('total_hits', 'DESC')->setMaxResults($limit);
    $result = $qb->executeQuery();
    return $result->fetchAll();
}

public function findByCollectiveAndPrefix(int $collectiveId, string $prefix, int $limit): array
{
    $qb = $this->db->getQueryBuilder();
    $qb->select('*')->from($this->tableName)->where($qb->expr()->eq('collective_id', $qb->createNamedParameter($collectiveId)))->andWhere($qb->expr()->like('term', $qb->createNamedParameter($prefix . '%')))->orderBy('num_hits', 'DESC')->setMaxResults($limit);
    return $this->findEntities($qb);
}

public function findByCollectiveAndStem(int $collectiveId, string $stem): array
{
    $qb = $this->db->getQueryBuilder();
    $qb->select('*')->from($this->tableName)->where($qb->expr()->eq('collective_id', $qb->createNamedParameter($collectiveId)))->andWhere($qb->expr()->eq('stem', $qb->createNamedParameter($stem)));
    return $this->findEntities($qb);
}

public function findByCollectiveAndTerm(int $collectiveId, string $term): ?\OCA\Collectives\Search\FileSearch\Db\SearchWord
{
    $qb = $this->db->getQueryBuilder();
    $qb->select('*')->from($this->tableName)->where($qb->expr()->eq('collective_id', $qb->createNamedParameter($collectiveId)))->andWhere($qb->expr()->eq('term', $qb->createNamedParameter($term)));
    try {
        return $this->findEntity($qb);
    } catch (\OCP\AppFramework\Db\DoesNotExistException|\OCP\AppFramework\Db\MultipleObjectsReturnedException) {
        return null;
    }
}

